package com.example;

import org.eclipse.jdt.core.ITypeRoot;
import org.eclipse.ui.IEditorPart;
import org.eclipse.jdt.ui.JavaUI; // Assume this type is available in Eclipse JDT UI

public class MyHoverProvider {
    protected ITypeRoot getEditorInputJavaElement(IEditorPart editor) {
        if (editor != null) {
            // Old API call
            return JavaUI.getEditorInputTypeRoot(editor.getEditorInput());
        }
        return null;
    }
}

afterExample:
package com.example;

import org.eclipse.jdt.core.ITypeRoot;
import org.eclipse.ui.IEditorPart;
import org.eclipse.jdt.internal.ui.javaeditor.EditorUtility; // Assume this type is available in Eclipse JDT UI

public class MyHoverProvider {
    protected ITypeRoot getEditorInputJavaElement(IEditorPart editor) {
        if (editor != null) {
            // New API call
            return EditorUtility.getEditorInputJavaElement(editor, false);
        }
        return null;
    }
}

